contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _val, address _log) public payable {
        require(_val > 0 || _val == 0);

        c.SetLogFile(_log); if (__ESBMC_reverted()) return;
        uint mBefore = c.MinSum(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.SetMinSum(_val); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint mAfter = c.MinSum(); if (__ESBMC_reverted()) return;

        assert(!reverted && mAfter == _val);
    }

    receive() external payable {}
}

