pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 _val, address _log) internal {
        vm.assume(_val > 0 || _val == 0);
        try c.SetLogFile(_log) {} catch { return; }
        uint256 mBefore;
        try c.MinSum() returns (uint256 __r) { mBefore = __r; } catch { return; }
        bool reverted;
        try c.SetMinSum(_val) { reverted = false; } catch { reverted = true; }
        uint256 mAfter;
        try c.MinSum() returns (uint256 __r) { mAfter = __r; } catch { return; }
        assertTrue(!reverted && mAfter == _val);
    }

    function testFuzz_run(uint256 _val, address _log) public {
